<?php
/**
 * Notification emails name each field by the label the visitor saw.
 *
 * Field names are generated by the editor (`field_ecbc26c5`, `select-662eef03`)
 * and were only ever meant for the form's markup. The `{all_fields}` summary
 * used to title-case them, so the site owner received "Field Ecbc26c5: …".
 *
 * Every case goes through handle_form_submission() and asserts on what
 * wp_mail() was handed, so the label resolution, the submission order and the
 * merge into the template are all covered together.
 *
 * @package DesignSetGo
 */

namespace DesignSetGo\Tests;

use WP_UnitTestCase;
use WP_REST_Request;
use DesignSetGo\Blocks\Form_Handler;

/**
 * @group forms
 */
class Test_Form_Email_Field_Labels extends WP_UnitTestCase {

	/**
	 * Captured wp_mail() arguments.
	 *
	 * @var array<string, mixed>|null
	 */
	private $sent;

	public function set_up() {
		parent::set_up();
		$this->sent = null;

		add_filter(
			'pre_wp_mail',
			function ( $short_circuit, $atts ) {
				$this->sent = $atts;
				return true;
			},
			10,
			2
		);

		// Block comments are HTML comments; kses would strip them without unfiltered_html.
		wp_set_current_user( self::factory()->user->create( array( 'role' => 'administrator' ) ) );
	}

	/**
	 * Publish a form with email notifications on and the default body.
	 *
	 * @param string $form_id    Form ID.
	 * @param string $fields     Serialized field blocks.
	 * @param string $extra_attr Extra JSON members for the form-builder comment (leading comma included).
	 * @return int Post ID.
	 */
	private function publish_form( $form_id, $fields, $extra_attr = '' ) {
		return self::factory()->post->create(
			array(
				'post_status'  => 'publish',
				// wp_insert_post() unslashes; slash so the JSON \u escapes survive.
				'post_content' => wp_slash(
					'<!-- wp:designsetgo/form-builder {"formId":"' . $form_id . '","enableEmail":true,"emailTo":"owner@example.org"' . $extra_attr . '} -->'
					. '<div class="wp-block-designsetgo-form-builder">' . $fields . '</div>'
					. '<!-- /wp:designsetgo/form-builder -->'
				),
			)
		);
	}

	/**
	 * Submit and return the email body that was sent.
	 *
	 * @param string $form_id Form ID.
	 * @param array  $fields  Map of field name => [ value, type ].
	 * @param int    $post_id Source post ID.
	 * @return string Email body.
	 */
	private function submit( $form_id, array $fields, $post_id ) {
		$list = array();
		foreach ( $fields as $name => $field ) {
			$list[] = array(
				'name'  => $name,
				'value' => $field[0],
				'type'  => $field[1],
			);
		}

		$request = new WP_REST_Request( 'POST', '/designsetgo/v1/form/submit' );
		$request->set_param( 'formId', $form_id );
		$request->set_param( 'fields', $list );
		$request->set_param( 'honeypot', '' );
		$request->set_param( 'timestamp', (string) ( ( time() - 60 ) * 1000 ) );
		$request->set_param( 'sourcePostId', $post_id );

		$result = ( new Form_Handler() )->handle_form_submission( $request );

		$this->assertNotWPError( $result, is_wp_error( $result ) ? $result->get_error_message() : '' );
		$this->assertNotNull( $this->sent, 'No email was sent.' );

		return (string) $this->sent['message'];
	}

	/**
	 * A field block comment, its attributes encoded the way the editor stores them.
	 *
	 * @param string $block Block name without the namespace.
	 * @param array  $attrs Block attributes.
	 * @return string Serialized block.
	 */
	private function field( $block, array $attrs ) {
		return '<!-- wp:designsetgo/' . $block . ' ' . serialize_block_attributes( $attrs ) . ' /-->';
	}

	/**
	 * The `<strong>Label:</strong> value` rows of the {all_fields} summary, in order.
	 *
	 * @param string $body Email body.
	 * @return array<int, array{0: string, 1: string}> Label/value pairs.
	 */
	private function rows( $body ) {
		preg_match_all( '#<strong>(.*?):</strong> (.*?)<br>#', $body, $matches, PREG_SET_ORDER );

		return array_map(
			static function ( $match ) {
				return array( $match[1], $match[2] );
			},
			$matches
		);
	}

	/**
	 * A contact form shaped like the bundled patterns: generated field names,
	 * authored labels, a label left at its default, and a phone field.
	 */
	public function test_generated_contact_form_uses_visible_labels_in_order() {
		$post_id = $this->publish_form(
			'contact',
			'<!-- wp:designsetgo/form-text-field {"fieldName":"field_3d375a5f","label":"Full Name","required":true} /-->'
			. '<!-- wp:designsetgo/form-email-field {"fieldName":"field_ecbc26c5","label":"Email Address","required":true} /-->'
			. '<!-- wp:designsetgo/form-phone-field {"fieldName":"phone-06f19e94"} /-->'
			. '<!-- wp:designsetgo/form-select-field {"fieldName":"select-662eef03","label":"Area of Interest","options":[{"label":"Design","value":"design"}]} /-->'
			. '<!-- wp:designsetgo/form-textarea-field {"fieldName":"field_79b62438"} /-->'
		);

		$body = $this->submit(
			'contact',
			array(
				'field_3d375a5f'             => array( 'Pat Lee', 'text' ),
				'field_ecbc26c5'             => array( 'pat@example.com', 'email' ),
				'phone-06f19e94'             => array( '555 123 4567', 'tel' ),
				'phone-06f19e94_country_code' => array( '+1', 'country_code' ),
				'select-662eef03'            => array( 'design', 'select' ),
				'field_79b62438'             => array( 'Hello there', 'textarea' ),
			),
			$post_id
		);

		$this->assertSame(
			array(
				array( 'Full Name', 'Pat Lee' ),
				array( 'Email Address', 'pat@example.com' ),
				array( 'Phone Number', '555 123 4567' ),
				array( 'Phone Number (country code)', '+1' ),
				array( 'Area of Interest', 'design' ),
				array( 'Message', 'Hello there' ),
			),
			$this->rows( $body )
		);

		foreach ( array( '3d375a5f', 'ecbc26c5', '06f19e94', '662eef03', '79b62438' ) as $hash ) {
			$this->assertStringNotContainsStringIgnoringCase( $hash, $body, "Generated field id {$hash} leaked into the email." );
		}
	}

	/**
	 * Hand-named custom fields keep their labels; the name is never shown instead.
	 */
	public function test_custom_fields_keep_their_labels() {
		$post_id = $this->publish_form(
			'custom',
			'<!-- wp:designsetgo/form-number-field {"fieldName":"team_size","label":"How many people are on your team?"} /-->'
			. $this->field(
				'form-checkbox-field',
				array(
					'fieldName' => 'consent',
					'label'     => 'I agree to the <a href="/terms">terms</a>',
				)
			)
		);

		$rows = $this->rows(
			$this->submit(
				'custom',
				array(
					'team_size' => array( '12', 'number' ),
					'consent'   => array( '1', 'checkbox' ),
				),
				$post_id
			)
		);

		$this->assertSame(
			array(
				array( 'How many people are on your team?', '12' ),
				array( 'I agree to the terms', '1' ),
			),
			$rows
		);
	}

	/**
	 * Fallbacks, in order: placeholder, then a hand-written field name, then a
	 * generic name. A generated id is never used.
	 */
	public function test_fields_without_a_label_get_a_readable_fallback() {
		$post_id = $this->publish_form(
			'fallback',
			'<!-- wp:designsetgo/form-text-field {"fieldName":"field_aaaa1111","label":"","placeholder":"Company name"} /-->'
			. '<!-- wp:designsetgo/form-text-field {"fieldName":"job_title","label":""} /-->'
			. '<!-- wp:designsetgo/form-text-field {"fieldName":"field_bbbb2222","label":"   "} /-->'
			. '<!-- wp:designsetgo/form-hidden-field {"fieldName":"utm_source","value":"ad"} /-->'
			. '<!-- wp:designsetgo/form-hidden-field {"fieldName":"hidden-cccc3333","value":"spring"} /-->'
		);

		$body = $this->submit(
			'fallback',
			array(
				'field_aaaa1111'  => array( 'Acme', 'text' ),
				'job_title'       => array( 'Owner', 'text' ),
				'field_bbbb2222'  => array( 'Something', 'text' ),
				'utm_source'      => array( 'ad', 'hidden' ),
				'hidden-cccc3333' => array( 'spring', 'hidden' ),
			),
			$post_id
		);

		$this->assertSame(
			array(
				array( 'Company name', 'Acme' ),
				array( 'Job Title', 'Owner' ),
				array( 'Untitled field', 'Something' ),
				array( 'Utm Source', 'ad' ),
				array( 'Hidden field', 'spring' ),
			),
			$this->rows( $body )
		);
		$this->assertStringNotContainsString( 'bbbb2222', $body );
		$this->assertStringNotContainsString( 'cccc3333', $body );
	}

	/**
	 * Two fields with the same label are numbered rather than merged or
	 * disambiguated by their internal names.
	 */
	public function test_duplicate_labels_are_numbered() {
		$post_id = $this->publish_form(
			'dupes',
			'<!-- wp:designsetgo/form-text-field {"fieldName":"field_11111111","label":"Name"} /-->'
			. '<!-- wp:designsetgo/form-text-field {"fieldName":"field_22222222","label":"name"} /-->'
			. '<!-- wp:designsetgo/form-text-field {"fieldName":"field_33333333","label":"Name"} /-->'
		);

		$rows = $this->rows(
			$this->submit(
				'dupes',
				array(
					'field_11111111' => array( 'Pat', 'text' ),
					'field_22222222' => array( 'Sam', 'text' ),
					'field_33333333' => array( 'Kim', 'text' ),
				),
				$post_id
			)
		);

		$this->assertSame(
			array(
				array( 'Name', 'Pat' ),
				array( 'name (2)', 'Sam' ),
				array( 'Name (3)', 'Kim' ),
			),
			$rows
		);
	}

	/**
	 * A label authored in another language arrives exactly as written, escaped
	 * once for the HTML body and unescaped in the plain-text subject.
	 */
	public function test_translated_labels_are_kept_verbatim() {
		$post_id = $this->publish_form(
			'translated',
			$this->field(
				'form-email-field',
				array(
					'fieldName' => 'field_dddd4444',
					'label'     => 'Correo electrónico',
				)
			)
			. $this->field(
				'form-text-field',
				array(
					'fieldName' => 'field_eeee5555',
					'label'     => 'Nombre & apellido',
				)
			),
			',"emailSubject":"Nuevo: {all_fields}"'
		);

		$body = $this->submit(
			'translated',
			array(
				'field_dddd4444' => array( 'ana@example.com', 'email' ),
				'field_eeee5555' => array( 'Ana Ruiz', 'text' ),
			),
			$post_id
		);

		$this->assertSame(
			array(
				array( 'Correo electrónico', 'ana@example.com' ),
				array( 'Nombre &amp; apellido', 'Ana Ruiz' ),
			),
			$this->rows( $body )
		);
		$this->assertSame(
			'Nuevo: Correo electrónico: ana@example.com; Nombre & apellido: Ana Ruiz',
			$this->sent['subject']
		);
	}

	/**
	 * Per-field merge tags still key on the field name: that is the author's
	 * token, not something shown to the recipient.
	 */
	public function test_field_merge_tags_still_use_the_field_name() {
		$post_id = $this->publish_form(
			'tags',
			'<!-- wp:designsetgo/form-text-field {"fieldName":"field_ffff6666","label":"Full Name"} /-->',
			',"emailBody":"From {field_ffff6666}"'
		);

		$body = $this->submit( 'tags', array( 'field_ffff6666' => array( 'Pat', 'text' ) ), $post_id );

		$this->assertStringContainsString( 'From Pat', $body );
	}
}
